def climbing_leaderboard(ranked: list[int], player: list[int]) -> list[int]:
    unique_ranked = sorted(list(set(ranked)), reverse=True)
    res = []
    i = len(unique_ranked) - 1
    for score in player:
        while i >= 0 and score >= unique_ranked[i]:
            i -= 1
        res.append(i + 2)
    return res
